  function threadMergeChanges(a,b){const out=[];for(const [path,label] of MERGE_FIELDS){const av=pathGet(a,path),bv=pathGet(b,path);if(JSON.stringify(av??null)!==JSON.stringify(bv??null))out.push({kind:'field',key:'field:'+path,path,label,a:av,b:bv})}const am=mergeTaskMap(a),bm=mergeTaskMap(b),ids=new Set([...Object.keys(am),...Object.keys(bm)]);for(const id of ids){const av=am[id],bv=bm[id];if(JSON.stringify(av??null)!==JSON.stringify(bv??null))out.push({kind:'task',key:'task:'+id,taskId:id,label:!av?'新增待辦':!bv?'刪除待辦':'待辦內容／狀態',a:av,b:bv})}return out}
  function resetMergePlan(diff){mergePlan={'global-read':'B','global-deleted':'B'};mergePreview=null;mergeReadChoice='B';mergeDeletedChoice='B';if(!diff)return;for(const t of diff.added||[])mergePlan['thread:'+t.threadId]='B';for(const t of diff.removed||[])mergePlan['thread:'+t.threadId]='B';for(const m of diff.modified||[]){mergePlan['thread:'+m.id]='M';for(const c of threadMergeChanges(m.a,m.b))mergePlan[m.id+'|'+c.key]='B'}}
