  function isPrimaryStock(x,symbol){const m=matchedStockEntry(x,symbol);if(!m)return false;if(typeof m.isPrimary==='boolean')return m.isPrimary;const title=norm(x?.title),sym=norm(symbol),name=norm(m.name||''),r=stockRelevance(x,symbol);const direct=title.includes(sym)||(name&&title.includes(name));const titleStocks=(x?.matchedStocks||[]).filter(z=>{const zs=norm(z.symbol||''),zn=norm(z.name||'');return(zs&&title.includes(zs))||(zn&&title.includes(zn))}).length;return !!(direct&&titleStocks===1&&r.score>=78)}
