  function stockIndex(){const m=new Map();for(const x of state.items){for(const z of (x.matchedStocks||[])){const symbol=String(z.symbol||'').trim(),name=String(z.name||symbol).trim();if(symbol&&!m.has(symbol))m.set(symbol,{symbol,name})}}return[...m.values()].sort((a,b)=>a.symbol.localeCompare(b.symbol,'zh-Hant'))}
