  function trackEntry(symbol,x){const m=(x.matchedStocks||[]).find(z=>String(z.symbol||'')===String(symbol))||{},now=new Date().toISOString(),st=editStamp();return{threadId:eventId(symbol,x),symbol:String(symbol),stockName:String(m.name||symbol),originEventId:eventId(symbol,x),originTitle:x.title||'',originUrl:x.url||'',originPublishedAt:x.publishedAt||'',categories:[...(x.categories||[])],keywords:topicKeywords(x),status:'追蹤中',closed:false,tasks:[],research:{hypothesis:'',validation:'',evidence:'',notes:'',result:'未驗證',conclusion:'',updatedAt:''},review:{keyEvidence:'',judgmentGap:'',lessons:'',summary:'',updatedAt:''},createdAt:now,_updatedAt:now,_modifiedBy:st,_fieldMeta:{status:st}}}
  function threadMatch(th,x){if(!matchedStock(x,th.symbol))return false;const ts=new Date(x.publishedAt||0).getTime(),base=new Date(th.originPublishedAt||0).getTime();if(base&&ts&&ts<base-3600000)return false;const cats=new Set(x.categories||[]),catHit=(th.categories||[]).some(c=>cats.has(c));const kws=new Set(topicKeywords(x).map(norm)),kwHits=(th.keywords||[]).filter(k=>kws.has(norm(k))).length;return kwHits>=1||(catHit&&(th.keywords||[]).length===0)}
