  function renderStocks(){const box=document.getElementById('newsStocks');if(!box)return;const selected=state.selectedStock!=='all'?stockMeta(state.selectedStock):null,favs=[...newsFavorites];const chips=favs.map(s=>`<button class="news-chip ${state.selectedStock===s.symbol?'active':''}" data-symbol="${esc(s.symbol)}" title="快速查看 ${esc(s.symbol)} ${esc(s.stockName)} 新聞">⭐ ${esc(s.symbol)} ${esc(s.stockName)}</button>`).join('');box.innerHTML=`<div class="news-favorite-bar"><div class="news-favorite-title"><b>⭐ 新聞收藏</b><span>${favs.length?`${favs.length} 檔快捷股票`:'尚未收藏股票'}</span></div><div class="news-favorite-scroll"><button class="news-chip ${state.selectedStock==='all'?'active':''}" data-symbol="all">全部新聞</button>${chips||'<span class="news-favorite-empty">搜尋股票後按「☆ 收藏」即可加入快捷列</span>'}${selected?`<button class="news-favorite-toggle ${isNewsFavorite(selected.symbol)?'saved':''}" data-fav-toggle="${esc(selected.symbol)}">${isNewsFavorite(selected.symbol)?'★ 已收藏・點擊取消':'☆ 收藏 '+esc(selected.symbol)}</button>`:''}</div></div>`;box.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{state.selectedStock=b.dataset.symbol;if(state.selectedStock!=='all')state.view='feed';savePrefs();renderStocks();render()});box.querySelectorAll('[data-fav-toggle]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleNewsFavorite(b.dataset.favToggle)})}
  async function fetchJson(url,opt={}){const controller=new AbortController(),timeoutMs=Number(opt.timeoutMs)||8000,t=setTimeout(()=>controller.abort(),timeoutMs);try{const r=await fetch(url,{cache:opt.cache||'no-store',signal:controller.signal,headers:{'Cache-Control':'no-cache','Pragma':'no-cache'}});if(!r.ok)throw Error(`HTTP ${r.status} @ ${url}`);const ct=r.headers.get('content-type')||'';if(!ct.includes('json')&&!String(url).includes('.json'))throw Error(`非 JSON 回應 @ ${url}`);return await r.json()}catch(e){if(e?.name==='AbortError')throw Error(`逾時 ${timeoutMs/1000} 秒 @ ${url}`);throw e}finally{clearTimeout(t)}}
  function payloadFreshnessTs(p){if(!p||typeof p!=='object')return 0;const vals=[p.generatedAt,p.updatedAt,p.generated_at,p.updated_at];let best=0;for(const v of vals){const t=new Date(v||0).getTime();if(Number.isFinite(t)&&t>best)best=t}for(const x of (Array.isArray(p.items)?p.items.slice(0,80):[])){const t=new Date(x?.publishedAt||x?.published_at||0).getTime();if(Number.isFinite(t)&&t>best)best=t}return best}
  function taipeiDateKey(v){const d=v instanceof Date?v:new Date(v);if(!Number.isFinite(d.getTime()))return'';try{return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}catch{return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}}
