  function latestArticleTs(p=state.payload){let best=0;for(const x of (p?.items||[])){const t=new Date(x?.publishedAt||0).getTime();if(Number.isFinite(t)&&t>best)best=t}return best}
  function newsFreshnessInfo(p=state.payload){const generated=payloadFreshnessTs(p),latest=latestArticleTs(p),now=Date.now(),today=taipeiDateKey(now),genDay=taipeiDateKey(generated),ageH=generated?Math.max(0,(now-generated)/36e5):Infinity;const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(new Date()))||0;const stale=!generated||(ageH>2.5)||((hour>=7&&hour<=23)&&genDay&&genDay!==today);return{generated,latest,ageH,stale,today,genDay}}
  function updateFreshnessBanner(){const el=document.getElementById('newsFreshnessBanner');if(!el||!state.payload)return;const f=newsFreshnessInfo();const source=state.newsDataSource?`｜來源：${esc(state.newsDataSource)}`:'';el.hidden=false;el.className=`news-freshness-banner ${f.stale?'stale':'ok'}`;el.innerHTML=f.stale?`<b>⚠ 新聞資料可能過期</b><span>資料檔：${fmtFresh(f.generated)}｜最新文章：${fmtFresh(f.latest)}${source}</span><button type="button" data-news-fresh-refresh>立即重新檢查</button>`:`<b>● 新聞資料已更新</b><span>資料檔：${fmtFresh(f.generated)}｜最新文章：${fmtFresh(f.latest)}${source}</span>`;el.querySelector('[data-news-fresh-refresh]')?.addEventListener('click',()=>loadNews({reason:'freshness'}))}
  function newsCandidates(file){const base=new URL('./',document.baseURI),stamp=`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,out=[new URL(`${file}${file.includes('?')?'&':'?'}t=${stamp}`,base).href],m=location.hostname.match(/^([^.]+)\.github\.io$/i),seg=location.pathname.split('/').filter(Boolean)[0];if(m&&seg){out.push(`https://raw.githubusercontent.com/${m[1]}/${seg}/main/${file}?t=${stamp}`);out.push(`https://raw.githubusercontent.com/${m[1]}/${seg}/master/${file}?t=${stamp}`)}return[...new Set(out)]}
