  function marketRegime(item,symbol){const dates=historyDates();if(!dates.length||!item?.publishedAt)return '待累積';const key=marketBenchmarkKeyForSymbol(symbol);if(!key)return '待累積';const eventDate=String(item.publishedAt).slice(0,10);let idx=dates.findIndex(d=>d>=eventDate&&Number(state.priceHistory?.benchmarks?.[d]?.[key])>0);if(idx<0)return '待累積';const vals=[];for(let i=0;i<=idx;i++){const v=Number(state.priceHistory?.benchmarks?.[dates[i]]?.[key]);if(v>0)vals.push(v)}if(vals.length<20)return '待累積';const now=vals.at(-1),ma20=avg(vals.slice(-20));if(now>ma20*1.01)return '多頭環境';if(now<ma20*.99)return '空頭環境';return '震盪環境'}
