  function crossStockStats(rows){const map=new Map();for(const r of rows){if(!map.has(r.symbol))map.set(r.symbol,{symbol:r.symbol,stockName:r.stockName,industry:r.industry,events:0,known:0,wins:0,market:[],industryEx:[]});const o=map.get(r.symbol);o.events++;const pt=r.r?.status==='ok'?r.r.points?.[state.crossHorizon]:null;if(Number.isFinite(pt?.marketExcessPct)){o.known++;o.market.push(pt.marketExcessPct);if(pt.marketExcessPct>0)o.wins++}if(Number.isFinite(pt?.industryExcessPct))o.industryEx.push(pt.industryExcessPct)}const arr=[...map.values()].map(o=>({...o,marketAvg:avg(o.market),industryAvg:avg(o.industryEx),winRate:o.known?o.wins/o.known*100:null}));if(state.crossSort==='market')arr.sort((a,b)=>(b.marketAvg??-999)-(a.marketAvg??-999)||b.known-a.known);else if(state.crossSort==='win')arr.sort((a,b)=>(b.winRate??-1)-(a.winRate??-1)||b.known-a.known);else arr.sort((a,b)=>b.known-a.known||b.events-a.events);return arr}
