  function dailyRows(){const now=Date.now(),days=Number(String(state.dailyWindow||'1d').replace('d',''))||1,today=taipeiDateKey(now),useCalendarToday=days===1,out=[];let source=state.items;if(useCalendarToday){const todays=state.items.filter(x=>taipeiDateKey(x.publishedAt||0)===today);if(todays.length)source=todays;else{const cut=now-86400000;source=state.items.filter(x=>new Date(x.publishedAt||0).getTime()>=cut)}}else{const cut=now-days*86400000;source=state.items.filter(x=>new Date(x.publishedAt||0).getTime()>=cut)}for(const x of source){const ts=new Date(x.publishedAt||0).getTime();if(!ts)continue;for(const m of (x.matchedStocks||[])){const symbol=String(m.symbol||''),stockName=String(m.name||symbol),market=m.market||state.priceHistory?.symbolMarkets?.[symbol]||'';if(!symbol)continue;const t=technicalSnapshot(x,symbol),industry=state.priceHistory?.symbolIndustries?.[symbol]?.industry||'未分類',imp=x.eventImportance||x.importance||0,multi=Math.max(1,x.clusterSources?.length||x.clusterSize||1),ageH=Math.max(0,(now-ts)/36e5);let score=imp+(ageH<=12?12:ageH<=24?8:0)+(multi>1?Math.min(8,(multi-1)*3):0);if(t?.volumeRatio>=1.5)score+=8;out.push({x,symbol,stockName,market,industry,t,score:Math.min(100,Math.round(score))})}}return out}
