  function updateTrackTabBadge(){if(!document.getElementById('newsTrackTab'))return;const n=Object.values(tracker.threads).reduce((sum,th)=>sum+threadEvents(th).filter(z=>!tracker.read[z.id]).length,0);newsTrackTab.textContent=n?`我的追蹤 (${n})`:'我的追蹤'}

  function ensureThreadMeta(th){th._fieldMeta=th._fieldMeta&&typeof th._fieldMeta==='object'?th._fieldMeta:{};if(!th.status)th.status=th.closed?'已結案':'追蹤中';if(!Array.isArray(th.tasks))th.tasks=[];if(!th.research||typeof th.research!=='object')th.research={};th.research={hypothesis:String(th.research.hypothesis||''),validation:String(th.research.validation||''),evidence:String(th.research.evidence||''),notes:String(th.research.notes||''),result:String(th.research.result||'未驗證'),conclusion:String(th.research.conclusion||''),updatedAt:String(th.research.updatedAt||'')};if(!th.review||typeof th.review!=='object')th.review={};th.review={keyEvidence:String(th.review.keyEvidence||''),judgmentGap:String(th.review.judgmentGap||''),lessons:String(th.review.lessons||''),summary:String(th.review.summary||''),updatedAt:String(th.review.updatedAt||'')};return th}
