  function addThreadTask(threadId,text){const th=tracker.threads[threadId];if(!th||!String(text||'').trim())return;ensureThreadMeta(th);const task={id:`task-${Date.now().toString(36)}-${hashText(text).slice(0,4)}`,text:String(text).trim(),kind:'手動',date:'',auto:false,done:false,createdAt:new Date().toISOString(),_meta:editStamp()};th.tasks.push(task);auditChange(threadId,'task:'+task.id,'新增待辦',null,task);touchThread(th,'tasks');saveTracker()}
