  function trackingTaskPanel(th){ensureThreadMeta(th);const auto=autoThreadTasks(th),manual=th.tasks||[],all=[...manual,...auto],pending=manual.filter(t=>!t.done).length,nextDate=nextThreadDate(th);return`<section class="track-workbench"><div class="track-workbench-head"><div><span>研究狀態與待辦</span><b>${esc(th.status||'追蹤中')}</b></div><div class="track-status-actions"><select data-track-status="${esc(th.threadId)}"><option ${th.status==='追蹤中'?'selected':''}>追蹤中</option><option ${th.status==='待確認'?'selected':''}>待確認</option><option ${th.status==='已確認'?'selected':''}>已確認</option><option ${th.status==='已結案'?'selected':''}>已結案</option></select></div></div><div class="track-workbench-summary"><span>手動待辦 ${pending}</span><span>自動提示 ${auto.length}</span><span>${nextDate?`下一重要日期 ${esc(nextDate)}`:'尚無已辨識重要日期'}</span></div><div class="track-task-add"><input data-track-task-input="${esc(th.threadId)}" placeholder="新增研究待辦，例如：確認法說是否下修全年展望"><button data-track-task-add="${esc(th.threadId)}">新增</button></div><div class="track-task-list">${all.length?all.map(t=>`<div class="track-task ${t.done?'done':''} ${t.auto?'auto':''}"><label>${t.auto?'<span class="track-task-icon">AUTO</span>':`<input type="checkbox" data-track-task-toggle="${esc(th.threadId)}" data-task-id="${esc(t.id)}" ${t.done?'checked':''}>`}<span>${esc(t.text)}</span></label><small>${esc(t.kind||'')}${t.date?` · ${esc(t.date)}`:''}${t.auto?' · 系統提示':''}</small></div>`).join(''):'<div class="daily-empty">目前沒有待辦或自動提示。</div>'}</div></section>`}

