  function reviewCorpus(th){ensureThreadMeta(th);return norm(`${th.review?.judgmentGap||''} ${th.review?.lessons||''} ${th.review?.summary||''} ${th.research?.conclusion||''}`)}
  function classifyResearchErrors(th){const txt=reviewCorpus(th);return ERROR_PATTERNS.filter(p=>p.re.test(txt))}
  function researchErrorStats(){const cases=reviewedThreads();const map=new Map(ERROR_PATTERNS.map(p=>[p.id,{...p,count:0,cases:[]}])) ;let withGap=0;for(const th of cases){if(String(th.review?.judgmentGap||'').trim())withGap++;for(const ptn of classifyResearchErrors(th)){const row=map.get(ptn.id);row.count++;row.cases.push(th)}}const patterns=[...map.values()].filter(x=>x.count>0).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label));return{cases,withGap,patterns,totalTagged:patterns.reduce((n,x)=>n+x.count,0)}}
  function researchErrorPanel(){const st=researchErrorStats(),enough=st.cases.length>=5,top=st.patterns.slice(0,6);const checklist=(top.length?top:ERROR_PATTERNS.slice(0,4)).slice(0,5);return`<section class="error-lab"><div class="error-lab-head"><div><span>研究錯誤模式統計</span><b>${enough?'開始形成個人模式':'樣本仍少'}</b></div><small>${st.cases.length} 個已結案／已回顧案例 · ${st.withGap} 個有判斷偏差紀錄</small></div>${st.cases.length?`<div class="error-pattern-grid">${top.length?top.map((x,i)=>`<article class="error-pattern-card"><div><b>${i+1}</b><span>${esc(x.label)}</span></div><strong>${x.count}</strong><small>次出現 · ${Math.round(x.count/st.cases.length*100)}% 案例</small><p>${esc(x.check)}</p></article>`).join(''):`<div class="error-empty">已有研究回顧，但目前「判斷偏差／教訓」尚未符合可分類模式。繼續記錄幾個案例後會逐步形成統計。</div>`}</div>`:`<div class="error-empty">目前還沒有可用的已結案研究回顧。先完成幾個事件的「判斷偏差」與「可複用教訓」，這裡才會開始建立你的個人研究模式。</div>`}<div class="personal-checklist"><div class="personal-checklist-title"><span>研究前個人檢查清單</span><small>${enough?'依你的高頻錯誤排序':'先用目前已出現模式；樣本增加後會自動重排'}</small></div><div class="personal-checklist-items">${checklist.map((x,i)=>`<label><input type="checkbox"><span><b>${i+1}. ${esc(x.label)}</b>${esc(x.check)}</span></label>`).join('')}</div></div><p class="error-lab-note">這些分類只整理你自己在研究回顧中留下的文字，目的是提醒反覆出現的研究疏漏；不是投資評分，也不代表未被分類的部分沒有風險。</p></section>`}
  function threadOriginEvent(th){const ev=threadEvents(th).find(z=>z.id===th.originEventId)||threadEvents(th).at(-1);return ev?.x||null}
  function threadSimilarity(target,candidate){ensureThreadMeta(target);ensureThreadMeta(candidate);const tx=threadOriginEvent(target),cx=threadOriginEvent(candidate);const sameCompany=target.symbol===candidate.symbol?1:0;const ti=industryLabelForSymbol(target.symbol),ci=industryLabelForSymbol(candidate.symbol),sameIndustry=ti&&ci&&ti!=='未分類'&&ti===ci?1:0;const cat=overlapScore(target.categories,candidate.categories);const kw=jaccardTokens(`${target.originTitle} ${(target.keywords||[]).join(' ')}`,`${candidate.originTitle} ${(candidate.keywords||[]).join(' ')}`);const hyp=jaccardTokens(target.research?.hypothesis||target.originTitle,candidate.research?.hypothesis||candidate.originTitle);const conclusion=jaccardTokens(`${target.research?.conclusion||''} ${target.review?.summary||''}`,`${candidate.research?.conclusion||''} ${candidate.review?.summary||''}`);let tech=0,regime=0;try{if(tx&&cx){const tt=technicalSnapshot(tx,target.symbol),ct=technicalSnapshot(cx,candidate.symbol);if(tt?.trend&&ct?.trend&&tt.trend===ct.trend)tech=1;const tr=marketRegime(tx,target.symbol),cr=marketRegime(cx,candidate.symbol);if(tr!=='待累積'&&tr===cr)regime=1}}catch{}const score=Math.round(sameCompany*18+sameIndustry*10+cat*24+kw*20+hyp*12+conclusion*6+tech*5+regime*5);const reasons=[];if(sameCompany)reasons.push('同一公司');else if(sameIndustry)reasons.push('同產業');if(cat>.3)reasons.push('事件類型相近');if(kw>.15)reasons.push('事件關鍵詞相近');if(hyp>.12)reasons.push('研究假設相近');if(conclusion>.12)reasons.push('結論語意相近');if(tech)reasons.push('技術背景相近');if(regime)reasons.push('市場環境相近');return{score,reasons,industry:ci}}
