  function experiencePanel(th){const sims=similarReviewedThreads(th);return`<section class="track-experience"><div class="track-experience-head"><div><span>研究經驗資料庫</span><b>${sims.length?`${sims.length} 個相似案例`:'尚無相似案例'}</b></div><small>只比對已結案／已回顧研究</small></div>${sims.length?`<div class="track-experience-list">${sims.map(s=>{const c=s.th,rv=c.review||{},r=c.research||{};return`<article class="experience-card"><div class="experience-top"><div><b>${s.score}% 相似</b><span>${esc(c.symbol)} ${esc(c.stockName)}</span></div><small>${esc(s.industry||'未分類')}</small></div><h4>${esc(c.originTitle)}</h4><p class="experience-why">${esc(s.reasons.join('、')||'綜合研究特徵相近')}</p><div class="experience-grid"><div><small>最終驗證</small><b>${esc(r.result||'未驗證')}</b></div><div><small>判斷偏差</small><p>${esc(rv.judgmentGap||'尚未記錄')}</p></div><div><small>可複用教訓</small><p>${esc(rv.lessons||'尚未記錄')}</p></div><div><small>回顧摘要</small><p>${esc(rv.summary||r.conclusion||'尚未記錄')}</p></div></div></article>`}).join('')}</div>`:`<div class="experience-empty">目前沒有達到相似門檻的已結案研究。隨著你的回顧案例增加，這裡會逐步形成自己的研究經驗庫。</div>`}<p class="experience-note">相似度用於找歷史研究案例，不代表未來股價走勢，也不構成買賣建議。</p></section>`}


  function threadOpenTasks(th){ensureThreadMeta(th);return (th.tasks||[]).filter(t=>!t.done)}
