  function researchWorkPriority(th){ensureThreadMeta(th);const unread=threadUnreadCount(th),tasks=threadOpenTasks(th).length,last=threadLastEvent(th),imp=last?.eventImportance||last?.importance||0;let score=Math.min(35,unread*10)+Math.min(25,tasks*8)+Math.min(20,Math.max(0,imp-60));if(th.status==='待確認')score+=14;else if(th.status==='追蹤中')score+=7;if(th.status==='已結案'||th.closed)score-=35;const age=(Date.now()-threadUpdatedTs(th))/86400000;if(age<=1)score+=12;else if(age<=3)score+=6;return Math.max(0,Math.min(100,Math.round(score)))}
  function researchDashThread(th,mode='priority'){ensureThreadMeta(th);const unread=threadUnreadCount(th),tasks=threadOpenTasks(th),last=threadLastEvent(th),score=researchWorkPriority(th),r=th.research||{},rv=th.review||{};const status=th.status||'追蹤中';return`<article class="research-dash-card ${status==='已結案'?'closed':''}"><div class="research-dash-top"><div><span class="dash-symbol">${esc(th.symbol)} ${esc(th.stockName||'')}</span><span class="dash-status">${esc(status)}</span></div>${mode==='priority'?`<b>${score}</b>`:`<time>${fmtDate(last?.publishedAt||th.createdAt)}</time>`}</div><h4>${esc(th.originTitle||last?.title||'未命名研究事件')}</h4><div class="dash-mini-kpis"><span>未讀 <b>${unread}</b></span><span>待辦 <b>${tasks.length}</b></span><span>驗證 <b>${esc(r.result||'未驗證')}</b></span></div>${last?`<p>${esc(last.title||'').slice(0,110)}</p>`:''}${rv.judgmentGap?`<div class="dash-warning">回顧偏差：${esc(rv.judgmentGap).slice(0,110)}</div>`:''}<button data-track-open="${esc(th.symbol)}">開啟個股研究</button></article>`}
  function renderResearchDashboard(){newsOverviewWindow.hidden=true;[newsDailyTab,newsResearchDashboardTab,newsTrackTab,newsDashboardTab,newsFeedTab,newsOverviewTab,newsDatabaseTab,newsCrossTab,newsRadarTab].forEach(x=>x.classList.remove('active'));newsResearchDashboardTab.classList.add('active');const st=trackingStats(),threads=st.threads;const open=threads.filter(th=>!(th.status==='已結案'||th.closed)),closed=threads.filter(th=>th.status==='已結案'||th.closed),openTasks=open.reduce((n,th)=>n+threadOpenTasks(th).length,0),awaiting=open.filter(th=>th.status==='待確認').length,active=open.filter(th=>th.status==='追蹤中').length;const priority=[...open].sort((a,b)=>researchWorkPriority(b)-researchWorkPriority(a)||threadUpdatedTs(b)-threadUpdatedTs(a)).slice(0,8);const recent=[...open].filter(th=>threadUnreadCount(th)>0).sort((a,b)=>threadUpdatedTs(b)-threadUpdatedTs(a)).slice(0,6);const stuck=[...open].filter(th=>threadOpenTasks(th).length>0&&threadUnreadCount(th)===0).sort((a,b)=>threadOpenTasks(b).length-threadOpenTasks(a).length||threadUpdatedTs(a)-threadUpdatedTs(b)).slice(0,6);const recentClosed=[...closed].sort((a,b)=>threadUpdatedTs(b)-threadUpdatedTs(a)).slice(0,5);const errs=researchErrorStats().patterns.slice(0,4);newsStatus.textContent=`研究儀表板｜${open.length} 個進行中研究｜${st.unread.length} 則未讀後續｜${openTasks} 個未完成待辦`;newsSummary.innerHTML=`<div class="news-stat"><small>進行中研究</small><b>${open.length}</b><em>${active} 追蹤中／${awaiting} 待確認</em></div><div class="news-stat"><small>未讀後續</small><b>${st.unread.length}</b><em>需要回看新進展</em></div><div class="news-stat"><small>未完成待辦</small><b>${openTasks}</b><em>研究工作項目</em></div><div class="news-stat"><small>已結案</small><b>${closed.length}</b><em>${st.reviewed} 個已有回顧</em></div>`;newsList.innerHTML=`<section class="research-dash-hero"><div><span class="overview-kicker">RESEARCH WORKSPACE</span><h2>完整研究儀表板</h2><p>集中查看目前研究工作量、未讀後續、待辦、卡住的研究與最近結案。優先度只表示「研究處理順序」，不是股票評分或買賣訊號。</p></div><div class="research-dash-pulse"><b>${priority[0]?researchWorkPriority(priority[0]):0}</b><span>最高研究優先度</span></div></section><section class="research-dash-section"><div class="research-dash-title"><h3>今天優先處理</h3><span>依未讀、待辦、事件重要性與新近度排序</span></div><div class="research-dash-grid">${priority.length?priority.map(th=>researchDashThread(th,'priority')).join(''):'<div class="news-empty">目前沒有進行中的研究。</div>'}</div></section><section class="research-dash-split"><div class="research-dash-section"><div class="research-dash-title"><h3>最近有新進展</h3><span>仍有未讀後續</span></div><div class="research-dash-list">${recent.length?recent.map(th=>researchDashThread(th,'recent')).join(''):'<div class="daily-empty">目前沒有未讀後續。</div>'}</div></div><div class="research-dash-section"><div class="research-dash-title"><h3>可能卡住的研究</h3><span>有待辦但暫無新後續</span></div><div class="research-dash-list">${stuck.length?stuck.map(th=>researchDashThread(th,'recent')).join(''):'<div class="daily-empty">目前沒有明顯卡住的研究。</div>'}</div></div></section><section class="research-dash-split"><div class="research-dash-section"><div class="research-dash-title"><h3>最近結案</h3><span>回頭檢視研究品質</span></div><div class="research-dash-list">${recentClosed.length?recentClosed.map(th=>researchDashThread(th,'recent')).join(''):'<div class="daily-empty">尚無已結案研究。</div>'}</div></div><div class="research-dash-section blindspot-panel"><div class="research-dash-title"><h3>最近常見研究盲點</h3><span>${researchErrorStats().cases.length<5?'樣本仍少':'依歷史回顧統計'}</span></div>${errs.length?`<div class="blindspot-list">${errs.map((x,i)=>`<div><b>${i+1}</b><span><strong>${esc(x.label)}</strong><small>${x.count} 次｜${esc(x.check)}</small></span></div>`).join('')}</div>`:'<div class="daily-empty">完成更多研究回顧後，這裡會顯示高頻錯誤模式。</div>'}</div></section>`;newsList.querySelectorAll('[data-track-open]').forEach(b=>b.onclick=()=>{state.selectedStock=b.dataset.trackOpen;state.view='overview';savePrefs();renderStocks();render()})}
  function trackingStats(){const threads=Object.values(tracker.threads);threads.forEach(ensureThreadMeta);const events=threads.flatMap(th=>threadEvents(th).map(z=>({...z,th}))),unread=events.filter(z=>!tracker.read[z.id]),reviewed=threads.filter(th=>{const rv=th.review||{};return!!(rv.keyEvidence||rv.judgmentGap||rv.lessons||rv.summary)}).length;return{threads,events,unread,reviewed,stocks:new Set(threads.map(t=>t.symbol)).size}}

  function extractNumbers(x){const txt=`${x?.title||''} ${x?.summary||''}`,out=[];for(const m of txt.matchAll(/(?:NT\$|US\$|\$)?\s*([+-]?\d+(?:\.\d+)?)\s*(%|％|億元|億|萬元|萬|元|美元|季|年|月|倍|bps|bp)?/gi)){const raw=m[0].trim();if(raw.length<2)continue;out.push(raw)}return[...new Set(out)].slice(0,10)}
  const riskWords=['下修','降評','虧損','衰退','下滑','減產','砍單','停工','裁員','違約','訴訟','調查','風險','庫存增加','毛利率下滑','營收下滑','獲利下滑','展望保守','不如預期'];
  const reliefWords=['上修','升評','成長','創高','增加','改善','回升','擴產','接單','訂單增加','毛利率提升','獲利成長','展望樂觀','優於預期'];
  function wordHits(x,words){const t=`${x?.title||''} ${x?.summary||''}`.toLowerCase();return words.filter(w=>t.includes(w.toLowerCase()))}
  function trackingDelta(th){const ev=threadEvents(th);const origin=ev.find(z=>z.id===th.originEventId)?.x||ev[ev.length-1]?.x;const latest=ev[0]?.x;if(!origin||!latest)return{status:'資料不足',cls:'neutral',items:[],origin,latest};if(eventId(th.symbol,origin)===eventId(th.symbol,latest))return{status:'尚無後續',cls:'neutral',items:['目前只有追蹤起點，尚未出現新的相關事件。'],origin,latest};const items=[];const oNums=new Set(extractNumbers(origin)),lNums=extractNumbers(latest),newNums=lNums.filter(n=>!oNums.has(n));if(newNums.length)items.push(`新增數字：${newNums.slice(0,5).join('、')}`);const os=origin.sentiment||'中性/待確認',ls=latest.sentiment||'中性/待確認';if(os!==ls)items.push(`情緒標記：${os} → ${ls}`);const or=wordHits(origin,riskWords),lr=wordHits(latest,riskWords),newRisk=lr.filter(w=>!or.includes(w));if(newRisk.length)items.push(`新增風險詞：${newRisk.slice(0,5).join('、')}`);const op=wordHits(origin,reliefWords),lp=wordHits(latest,reliefWords),newPos=lp.filter(w=>!op.includes(w));if(newPos.length)items.push(`新增正向詞：${newPos.slice(0,5).join('、')}`);const removedRisk=or.filter(w=>!lr.includes(w));if(removedRisk.length)items.push(`原風險詞未再出現：${removedRisk.slice(0,4).join('、')}`);const oCats=new Set(origin.categories||[]),newCats=(latest.categories||[]).filter(c=>!oCats.has(c));if(newCats.length)items.push(`新增事件類型：${newCats.slice(0,4).join('、')}`);let status='資訊更新',cls='neutral';if(newRisk.length||ls==='偏負面'&&os!=='偏負面'){status='風險升高',cls='neg'}else if(newPos.length||ls==='偏正面'&&os!=='偏正面'){status='正向改善',cls='pos'}else if(removedRisk.length){status='風險可能緩解',cls='pos'}if(!items.length)items.push('目前後續內容與原始事件高度相近，尚未偵測到明顯的新數字或風險／正向詞變化。');return{status,cls,items,origin,latest}}
  function trackingDeltaPanel(th){const d=trackingDelta(th);return`<section class="track-delta ${d.cls}"><div class="track-delta-head"><div><span class="track-delta-label">事件變化摘要</span><b>${esc(d.status)}</b></div>${d.latest&&d.origin&&d.latest!==d.origin?`<span>${fmtDate(d.origin.publishedAt)} → ${fmtDate(d.latest.publishedAt)}</span>`:''}</div><ul>${d.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${d.latest?.url&&d.origin&&d.latest!==d.origin?`<div class="track-delta-links"><a href="${esc(d.origin.url||'#')}" target="_blank" rel="noopener noreferrer">原始事件</a><a href="${esc(d.latest.url)}" target="_blank" rel="noopener noreferrer">最新後續</a></div>`:''}</section>`}
  function timelineStage(x,isOrigin=false,isLatest=false){if(isOrigin)return{label:'事件開始',cls:'start'};const txt=`${x?.title||''} ${x?.summary||''} ${(x?.categories||[]).join(' ')}`;if(/公司回應|澄清|說明|聲明|回應|證實|否認/.test(txt))return{label:'公司回應',cls:'reply'};if(/法說|法人說明會|重大訊息|公告|董事會|財報|季報|年報/.test(txt))return{label:'法說／公告',cls:'official'};if(/營收|EPS|毛利率|獲利|虧損|出貨|訂單|接單|產能|資本支出|月增|年增|年減|成長率/.test(txt))return{label:'數據更新',cls:'data'};if(isLatest)return{label:'最新狀態',cls:'latest'};return{label:'事件進展',cls:'update'}}
  function trackingTimeline(th){const ev=threadEvents(th).slice().reverse();if(!ev.length)return'';const originId=th.originEventId,latestId=ev[ev.length-1]?.id;let lastStage='';const rows=ev.slice(-40).map((z,i)=>{const x=z.x,isOrigin=z.id===originId,isLatest=z.id===latestId&&!isOrigin,stage=timelineStage(x,isOrigin,isLatest);const stageChanged=stage.label!==lastStage;lastStage=stage.label;const imp=x.eventImportance||x.importance||0;return`<article class="track-timeline-row ${stage.cls}"><div class="track-timeline-axis"><span></span></div><div class="track-timeline-body"><div class="track-timeline-meta"><time>${fmtDate(x.publishedAt)}</time><span class="track-stage ${stage.cls}">${esc(stage.label)}</span>${stageChanged&&i>0?'<span class="track-stage-shift">階段轉換</span>':''}<span class="mini-badge ${imp>=70?'major':''}">${imp}</span><span>${esc(x.source||'')}</span></div><h4><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></h4>${x.summary?`<p>${esc(x.summary).slice(0,180)}</p>`:''}<div class="track-timeline-tags">${(x.categories||[]).slice(0,3).map(c=>`<span>${esc(c)}</span>`).join('')}${(x.mentionedDates||[]).slice(0,2).map(d=>`<span>日期 ${esc(d)}</span>`).join('')}</div></div></article>`}).join('');const stageNow=timelineStage(ev[ev.length-1]?.x,ev.length===1,true);return`<section class="track-timeline-panel"><div class="track-timeline-title"><div><span>事件發展時間軸</span><b>${esc(stageNow.label)}</b></div><small>${ev.length} 個事件節點 · 由舊到新</small></div><div class="track-timeline">${rows}</div>${ev.length>40?`<div class="track-more">僅顯示最近 40 個節點，另有 ${ev.length-40} 個較舊節點。</div>`:''}</section>`}

  const FIELD_LABELS=Object.fromEntries(MERGE_FIELDS);
  function modificationTimeline(th){ensureThreadMeta(th);const latest=Object.entries(th._fieldMeta||{}).map(([path,m])=>({path,label:FIELD_LABELS[path]||path,...m}));for(const t of (th.tasks||[]))if(t._meta?.at)latest.push({path:'task:'+t.id,label:'待辦：'+String(t.text||'').slice(0,36),...t._meta});latest.sort((a,b)=>new Date(b.at)-new Date(a.at));const audit=(tracker.audit||[]).filter(x=>x.threadId===th.threadId).sort((a,b)=>new Date(b.at)-new Date(a.at));if(!latest.length&&!audit.length)return'';const short=v=>{const s=typeof v==='string'?v:JSON.stringify(v??'');return esc(s.length>70?s.slice(0,70)+'…':s)};return `<section class="mod-history"><div class="mod-history-head"><span>研究修改時間線</span><b>${audit.length||latest.length} 筆</b></div><div class="mod-history-list">${(audit.length?audit.slice(0,20):latest.slice(0,12)).map(r=>`<div class="audit-row"><span>${esc(r.label)}</span><small>${esc(metaText(r))}</small>${r.id?`<em>${short(r.before)} → ${short(r.after)}</em>`:''}</div>`).join('')}</div></section>`}
  function conflictMeta(c,side,p){if(c.kind==='field'){const th=(side==='base'?p.base:side==='a'?p.local:p.remote)?.threads?.[c.threadId];return th?._fieldMeta?.[c.path]||th?._modifiedBy}if(c.kind==='task'){const th=(side==='base'?p.base:side==='a'?p.local:p.remote)?.threads?.[c.threadId];return (th?.tasks||[]).find(t=>t.id===c.taskId)?._meta||th?._modifiedBy}if(c.kind==='thread'){const th=(side==='base'?p.base:side==='a'?p.local:p.remote)?.threads?.[c.threadId];return th?._modifiedBy||th?._fieldMeta?.status}return null}
  function trackingThreadCard(th){const events=threadEvents(th),unread=events.filter(z=>!tracker.read[z.id]),latest=events[0]?.x,origin=events.find(z=>z.id===th.originEventId)?.x;return`<article class="track-thread ${unread.length?'has-unread':''}"><div class="track-thread-head"><div><span class="track-stock">${esc(th.symbol)} ${esc(th.stockName)}</span><span class="track-count">${events.length} 則 · ${unread.length} 未讀</span></div><div class="track-thread-actions"><button data-track-thread-read="${esc(th.threadId)}">全部已讀</button><button class="danger" data-untrack-thread="${esc(th.threadId)}">取消追蹤</button></div></div><h3>${esc(th.originTitle)}</h3><div class="track-topic-tags">${(th.categories||[]).slice(0,3).map(c=>`<span>${esc(c)}</span>`).join('')}${(th.keywords||[]).slice(0,5).map(k=>`<span>#${esc(k)}</span>`).join('')}</div><div class="track-origin"><span>追蹤起點 ${fmtDate(th.originPublishedAt)}</span>${origin?.url?`<a href="${esc(origin.url)}" target="_blank" rel="noopener noreferrer">原始事件</a>`:''}<button data-track-open="${esc(th.symbol)}">個股研究</button></div>${trackingDeltaPanel(th)}${trackingTaskPanel(th)}${trackingResearchPanel(th)}${experiencePanel(th)}${trackingReviewPanel(th)}${modificationTimeline(th)}${trackingTimeline(th)}<div class="track-event-list">${events.slice(0,30).map(z=>trackingEventRow(th,z)).join('')||'<div class="daily-empty">尚無相關後續新聞</div>'}</div>${events.length>30?`<div class="track-more">另有 ${events.length-30} 則較舊事件未展開</div>`:''}</article>`}
  function trackingEventRow(th,z){const x=z.x,read=!!tracker.read[z.id],isOrigin=z.id===th.originEventId,imp=x.eventImportance||x.importance||0;return`<div class="track-event ${read?'is-read':'is-unread'}"><div class="track-event-dot"></div><div class="track-event-main"><div class="track-event-meta"><time>${fmtDate(x.publishedAt)}</time>${isOrigin?'<span>追蹤起點</span>':''}<span class="mini-badge ${imp>=70?'major':''}">${imp}</span><span>${esc(x.source||'')}</span></div><h4><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></h4><p>${esc(x.summary||'').slice(0,180)}</p></div>${eventActions(th.symbol,x,true)}</div>`}
  function renderTracking(){newsOverviewWindow.hidden=true;[newsDailyTab,newsResearchDashboardTab,newsTrackTab,newsDashboardTab,newsFeedTab,newsOverviewTab,newsDatabaseTab,newsCrossTab,newsRadarTab].forEach(x=>x.classList.remove('active'));newsTrackTab.classList.add('active');const st=trackingStats();let threads=[...st.threads].sort((a,b)=>{const au=threadEvents(a).filter(z=>!tracker.read[z.id]).length,bu=threadEvents(b).filter(z=>!tracker.read[z.id]).length;if(bu!==au)return bu-au;return new Date(threadEvents(b)[0]?.x?.publishedAt||b.createdAt)-new Date(threadEvents(a)[0]?.x?.publishedAt||a.createdAt)});const q=norm(state.trackSearch);if(q)threads=threads.filter(th=>{ensureThreadMeta(th);const r=th.research||{},rv=th.review||{};return norm(`${th.symbol} ${th.stockName} ${th.originTitle} ${(th.categories||[]).join(' ')} ${(th.keywords||[]).join(' ')} ${r.hypothesis} ${r.validation} ${r.evidence} ${r.conclusion} ${rv.keyEvidence} ${rv.judgmentGap} ${rv.lessons} ${rv.summary}`).includes(q)});if(state.trackFilter==='unread')threads=threads.filter(th=>threadEvents(th).some(z=>!tracker.read[z.id]));else if(state.trackFilter==='reviewed')threads=threads.filter(th=>{ensureThreadMeta(th);const rv=th.review||{};return!!(rv.keyEvidence||rv.judgmentGap||rv.lessons||rv.summary)});else if(state.trackFilter==='closed')threads=threads.filter(th=>th.status==='已結案'||th.closed);newsStatus.textContent=`我的追蹤事件｜${st.threads.length} 個主題｜${st.unread.length} 則未讀後續｜資料更新 ${fmtDate(state.payload.generatedAt)}`;newsSummary.innerHTML=`<div class="news-stat"><small>追蹤主題</small><b>${st.threads.length}</b><em>本機保存</em></div><div class="news-stat"><small>未讀後續</small><b>${st.unread.length}</b><em>新抓到的相關事件</em></div><div class="news-stat"><small>追蹤公司</small><b>${st.stocks}</b><em>可重複追蹤不同主題</em></div><div class="news-stat"><small>研究回顧</small><b>${st.reviewed}</b><em>已建立歷史回顧</em></div>`;newsList.innerHTML=`<section class="track-hero"><div><span class="overview-kicker">FOLLOW-UP EVENT TRACKER</span><h2>我的追蹤事件</h2><p>把重要新聞標記成追蹤主題。之後同一公司、事件類型或關鍵詞相近的新新聞會自動集中到同一追蹤串；預設保存在本機；設定 Google Sheet + Apps Script 後，可在電腦、iPad、手機同步。</p></div><div class="track-pulse"><b>${st.unread.length}</b><span>未讀後續</span></div></section><section class="track-controls"><input id="trackSearch" value="${esc(state.trackSearch)}" placeholder="搜尋公司、事件主題、關鍵詞"><select id="trackFilter"><option value="all" ${state.trackFilter==='all'?'selected':''}>全部追蹤</option><option value="unread" ${state.trackFilter==='unread'?'selected':''}>只看有未讀</option><option value="reviewed" ${state.trackFilter==='reviewed'?'selected':''}>只看已有回顧</option><option value="closed" ${state.trackFilter==='closed'?'selected':''}>只看已結案</option></select></section>${syncPanel()}${researchErrorPanel()}<div class="track-thread-list">${threads.length?threads.map(trackingThreadCard).join(''):'<div class="news-empty">目前沒有符合條件的追蹤主題。你可以從每日情報、新聞列表或全台股雷達按下「☆ 追蹤」。</div>'}</div>`;document.getElementById('trackSearch')?.addEventListener('change',e=>{state.trackSearch=e.target.value;savePrefs();renderTracking()});document.getElementById('trackFilter')?.addEventListener('change',e=>{state.trackFilter=e.target.value;savePrefs();renderTracking()});newsList.querySelectorAll('[data-track-status]').forEach(sel=>sel.addEventListener('change',e=>{setThreadStatus(e.target.dataset.trackStatus,e.target.value);renderTracking()}));newsList.querySelectorAll('[data-track-task-toggle]').forEach(cb=>cb.addEventListener('change',e=>{toggleThreadTask(e.target.dataset.trackTaskToggle,e.target.dataset.taskId);renderTracking()}));newsList.querySelectorAll('[data-track-task-add]').forEach(btn=>btn.addEventListener('click',e=>{const id=e.currentTarget.dataset.trackTaskAdd,input=newsList.querySelector(`[data-track-task-input=\"${CSS.escape(id)}\"]`);addThreadTask(id,input?.value||'');renderTracking()}));newsList.querySelectorAll('[data-research-save]').forEach(btn=>btn.addEventListener('click',e=>{const id=e.currentTarget.dataset.researchSave,root=e.currentTarget.closest('[data-research-root]');saveThreadResearch(id,root);renderTracking()}));newsList.querySelectorAll('[data-review-save]').forEach(btn=>btn.addEventListener('click',e=>{const id=e.currentTarget.dataset.reviewSave,root=e.currentTarget.closest('[data-review-root]');saveThreadReview(id,root);renderTracking()}));newsList.querySelectorAll('[data-review-autofill]').forEach(btn=>btn.addEventListener('click',e=>{const id=e.currentTarget.dataset.reviewAutofill,root=e.currentTarget.closest('[data-review-root]');autoFillReview(id,root)}));bindSyncPanel()}
  function radarRows(){const now=Date.now(),days=Number(String(state.radarWindow).replace('d',''))||3,cut=now-days*86400000,out=[];for(const x of state.items){const ts=new Date(x.publishedAt||0).getTime();if(!ts||ts<cut)continue;for(const m of (x.matchedStocks||[])){const symbol=String(m.symbol||''),stockName=String(m.name||symbol),market=m.market||state.priceHistory?.symbolMarkets?.[symbol]||'';if(!symbol)continue;const t=technicalSnapshot(x,symbol),r=eventReaction(x,symbol),industry=state.priceHistory?.symbolIndustries?.[symbol]?.industry||'未分類';const ageH=Math.max(0,(now-ts)/36e5),imp=x.eventImportance||x.importance||0,multi=Math.max(1,x.clusterSources?.length||x.clusterSize||1);let score=imp+(ageH<=24?12:ageH<=72?6:0)+(multi>1?Math.min(8,(multi-1)*3):0);if(t?.volumeRatio>=1.5)score+=8;if(t?.trend==='多頭排列'||t?.trend==='空頭排列')score+=3;out.push({x,symbol,stockName,market,industry,t,r,score:Math.min(100,Math.round(score))})}}return out}
  function radarPass(row){const q=norm(state.radarSearch||'');if(q&&!norm(`${row.symbol} ${row.stockName} ${row.x.title} ${row.x.summary||''} ${row.industry}`).includes(q))return false;if(state.radarCategory!=='all'&&!(row.x.categories||[]).includes(state.radarCategory))return false;if(state.radarMarket!=='all'&&row.market!==state.radarMarket)return false;if(state.radarIndustry!=='all'&&row.industry!==state.radarIndustry)return false;if(state.radarMajorOnly&&(row.x.eventImportance||row.x.importance||0)<70)return false;if(state.radarVolume==='high'&&!(Number.isFinite(row.t?.volumeRatio)&&row.t.volumeRatio>=1.5))return false;if(state.radarVolume==='low'&&!(Number.isFinite(row.t?.volumeRatio)&&row.t.volumeRatio<=.7))return false;if(state.radarTrend==='above'&&!(Number.isFinite(row.t?.vsMa20)&&row.t.vsMa20>=0))return false;if(state.radarTrend==='below'&&!(Number.isFinite(row.t?.vsMa20)&&row.t.vsMa20<0))return false;return true}
  function radarCard(row){const imp=row.x.eventImportance||row.x.importance||0,vr=Number.isFinite(row.t?.volumeRatio)?row.t.volumeRatio.toFixed(2)+'×':'—',mkt=row.market==='otc'?'上櫃':'上市';return`<article class="radar-card"><div class="radar-card-head"><div><span class="radar-score">研究優先 ${row.score}</span><span class="mini-badge ${imp>=70?'major':''}">事件 ${imp}</span></div><time>${fmtDate(row.x.publishedAt)}</time></div><div class="radar-stock"><b>${esc(row.symbol)} ${esc(row.stockName)}</b><span>${mkt} · ${esc(row.industry)}</span></div><h4><a href="${esc(row.x.url)}" target="_blank" rel="noopener noreferrer">${esc(row.x.title)}</a></h4><div class="radar-tags">${(row.x.categories||[]).slice(0,2).map(c=>`<span>${esc(c)}</span>`).join('')}<span>${esc(row.x.sentiment||'中性/待確認')}</span></div><div class="radar-kpis"><div><small>量比</small><b>${vr}</b></div><div><small>技術位置</small><b>${esc(row.t?.trend||'待累積')}</b></div><div><small>MA20</small><b>${Number.isFinite(row.t?.vsMa20)?pctText(row.t.vsMa20):'—'}</b></div><div><small>多來源</small><b>${Math.max(1,row.x.clusterSources?.length||1)}</b></div></div><p>${esc(row.x.summary||'').slice(0,180)}</p><button data-radar-open="${esc(row.symbol)}">查看個股情報</button>${eventActions(row.symbol,row.x,true)}</article>`}
  function renderRadar(){newsOverviewWindow.hidden=true;[newsDailyTab,newsResearchDashboardTab,newsTrackTab,newsDashboardTab,newsFeedTab,newsOverviewTab,newsDatabaseTab,newsCrossTab].forEach(x=>x.classList.remove('active'));newsRadarTab.classList.add('active');const all=radarRows(),cats=[...new Set(all.flatMap(r=>r.x.categories||[]))].sort(),industries=[...new Set(all.map(r=>r.industry).filter(Boolean))].sort();let rows=all.filter(radarPass);if(state.radarSort==='newest')rows.sort((a,b)=>new Date(b.x.publishedAt)-new Date(a.x.publishedAt));else if(state.radarSort==='volume')rows.sort((a,b)=>(b.t?.volumeRatio||0)-(a.t?.volumeRatio||0)||b.score-a.score);else rows.sort((a,b)=>b.score-a.score||new Date(b.x.publishedAt)-new Date(a.x.publishedAt));const stocks=new Set(rows.map(r=>r.symbol)),major=rows.filter(r=>(r.x.eventImportance||r.x.importance||0)>=70),highVol=rows.filter(r=>r.t?.volumeRatio>=1.5);newsStatus.textContent=`全台股事件雷達｜近 ${String(state.radarWindow).replace('d','')} 天｜辨識 ${stocks.size} 檔公司｜${rows.length} 個事件股票組合`;newsSummary.innerHTML=`<div class="news-stat"><small>雷達公司</small><b>${stocks.size}</b><em>上市＋上櫃</em></div><div class="news-stat"><small>重大事件</small><b>${major.length}</b><em>重要性 ≥70</em></div><div class="news-stat"><small>放量事件</small><b>${highVol.length}</b><em>量比 ≥1.5×</em></div><div class="news-stat"><small>新聞覆蓋</small><b>${all.length}</b><em>可辨識公司事件</em></div>`;newsList.innerHTML=`<section class="radar-hero"><div><span class="overview-kicker">TAIWAN MARKET EVENT RADAR</span><h2>全台股事件雷達</h2><p>從近期公開財經新聞中辨識上市櫃公司，依事件重要性、時效、多來源與量價背景安排研究優先順序。這是研究排序，不是買賣推薦。</p></div><div class="radar-pulse"><b>${stocks.size}</b><span>事件公司</span></div></section><section class="radar-filters"><label>搜尋<input id="radarSearch" value="${esc(state.radarSearch)}" placeholder="代號、公司、新聞關鍵字"></label><label>期間<select id="radarWindow"><option value="1d" ${state.radarWindow==='1d'?'selected':''}>24小時</option><option value="3d" ${state.radarWindow==='3d'?'selected':''}>3天</option><option value="7d" ${state.radarWindow==='7d'?'selected':''}>7天</option><option value="30d" ${state.radarWindow==='30d'?'selected':''}>30天</option></select></label><label>市場<select id="radarMarket"><option value="all">全部市場</option><option value="listed" ${state.radarMarket==='listed'?'selected':''}>上市</option><option value="otc" ${state.radarMarket==='otc'?'selected':''}>上櫃</option></select></label><label>事件<select id="radarCategory"><option value="all">全部類型</option>${cats.map(c=>`<option value="${esc(c)}" ${state.radarCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>產業<select id="radarIndustry"><option value="all">全部產業</option>${industries.map(c=>`<option value="${esc(c)}" ${state.radarIndustry===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>量能<select id="radarVolume"><option value="all">全部</option><option value="high" ${state.radarVolume==='high'?'selected':''}>放量 ≥1.5×</option><option value="low" ${state.radarVolume==='low'?'selected':''}>量縮 ≤0.7×</option></select></label><label>技術<select id="radarTrend"><option value="all">全部</option><option value="above" ${state.radarTrend==='above'?'selected':''}>MA20 上方</option><option value="below" ${state.radarTrend==='below'?'selected':''}>MA20 下方</option></select></label><label>排序<select id="radarSort"><option value="score" ${state.radarSort==='score'?'selected':''}>研究優先度</option><option value="newest" ${state.radarSort==='newest'?'selected':''}>最新</option><option value="volume" ${state.radarSort==='volume'?'selected':''}>量比高</option></select></label><label class="radar-check"><input type="checkbox" id="radarMajorOnly" ${state.radarMajorOnly?'checked':''}>只看重大</label></section><div class="radar-grid">${rows.length?rows.slice(0,300).map(radarCard).join(''):'<div class="news-empty">目前沒有符合條件的事件。若剛升級 v2.9，請先讓 GitHub Actions 更新一次新聞資料以建立公司辨識。</div>'}</div>`;const on=(id,key,event='change')=>document.getElementById(id)?.addEventListener(event,e=>{state[key]=e.target.value;savePrefs();renderRadar()});on('radarSearch','radarSearch','input');on('radarWindow','radarWindow');on('radarMarket','radarMarket');on('radarCategory','radarCategory');on('radarIndustry','radarIndustry');on('radarVolume','radarVolume');on('radarTrend','radarTrend');on('radarSort','radarSort');document.getElementById('radarMajorOnly').onchange=e=>{state.radarMajorOnly=e.target.checked;savePrefs();renderRadar()};newsList.querySelectorAll('[data-radar-open]').forEach(b=>b.onclick=()=>{state.selectedStock=b.dataset.radarOpen;state.view='overview';savePrefs();renderStocks();render()})}
  function eventCard(g){const x=g.lead,imp=x.eventImportance||x.importance||0,sent=x.sentiment||'中性/待確認',sentCls=sent==='偏正面'?'pos':sent==='偏負面'?'neg':'',meta=eventGroupMeta(g),mergedSummary=eventMergedSummary(g);const trackSymbol=state.selectedStock!=='all'?state.selectedStock:((x.matchedStocks||[]).length===1?String(x.matchedStocks[0].symbol||''):'');return `<article class="news-card event-card"><div class="news-card-top"><span class="news-badge ${imp>=70?'high':''}">事件重要性 ${imp}</span><span class="news-badge ${sentCls}">${esc(sent)}</span>${relevanceBadge(x,state.selectedStock!=='all'?state.selectedStock:resolveStockQuery(state.search)?.symbol)}${g.items.length>1?`<span class="news-badge multi">${g.items.length} 篇／${meta.sources.length} 來源</span>`:''}${(x.categories||[]).slice(0,2).map(c=>`<span class="news-badge">${esc(c)}</span>`).join('')}</div><h3><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></h3><div class="news-meta"><span>${esc(x.source||'未知來源')}</span><span>${fmtDate(x.publishedAt)}</span>${g.items.length>1&&meta.earliest&&meta.latest?`<span>事件期間 ${fmtDate(meta.earliest.toISOString())} → ${fmtDate(meta.latest.toISOString())}</span>`:''}</div>${mergedSummary?`<p>${esc(mergedSummary).slice(0,360)}</p>`:''}<div class="news-analysis"><div><b>可能影響面向</b><div class="analysis-tags">${(x.impactAreas||['待確認影響']).map(a=>`<span>${esc(a)}</span>`).join('')}</div></div><div class="horizon-grid"><div><b>短期</b><p>${esc(x.horizons?.short||'先確認原始公告與第二來源。')}</p></div><div><b>中期</b><p>${esc(x.horizons?.mid||'追蹤後續公司公告與營運數據。')}</p></div><div><b>長期</b><p>${esc(x.horizons?.long||'回到基本面與產業趨勢評估。')}</p></div></div><div><b>接下來觀察</b><ul>${(x.watchSignals||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${(x.mentionedDates||[]).length?`<div class="mentioned-dates">新聞提及日期：${x.mentionedDates.map(esc).join('、')}</div>`:''}</div></div>${state.selectedStock!=='all'?reactionPanel(x,state.selectedStock):''}${eventSourceDetails(g,false)}${x.importanceReasons?.length?`<div class="news-why">重要性依據：${x.importanceReasons.map(esc).join('、')}</div>`:''}${trackSymbol?eventActions(trackSymbol,x):''}</article>`}

  window.StockNewsCenter={version:NEWS_APP_VERSION,open:()=>open(),openStock:async(symbol,view='overview')=>{symbol=String(symbol||'').trim().toUpperCase();if(!symbol)return;state.selectedStock=symbol;state.search='';state.view=view||'overview';state.readMode=state.readMode||'focus';savePrefs();await open();renderStocks();syncControls();render()}};

